  need(resource?.type==='lei-records'&&typeof lei==='string'&&/^[A-Z0-9]{20}$/.test(lei)&&typeof name==='string'&&name.trim(),'GLEIF_MONITORING_RESOURCE','Use a complete original GLEIF legal-entity record.');
