from __future__ import annotations

import gzip
import io
from pathlib import Path
from urllib.parse import urlsplit, parse_qs, unquote

from model import (Domain, Workspace, InputError, MAX_SOURCE, json_bytes, load_json,
                   MONITORING_DEFAULT, ndjson_application)
import matching
import updates
import review_cycles
import gleif_portfolio

HERE = Path(__file__).resolve().parent

class Handler(ndjson_application.Handler):
    server_version = "Starforge-Source-Monitoring"

    @property
    def domain(self):
        return self.server.domain

    def _cycle_branch(self):
        selected = unquote(self.headers.get("X-Review-Workspace", ""))
        if selected != str(self.domain.ws.root):
            raise InputError("Open the original workspace branch for this review cycle request")

    def _get(self):
        target = urlsplit(self.path)
        assets = {"/monitor": ("index.html", "text/html; charset=utf-8"),
                  "/monitor/": ("index.html", "text/html; charset=utf-8"),
                  "/monitor/app.js": ("app.js", "text/javascript; charset=utf-8"),
                  "/monitor/gleif-intake.js": ("gleif-intake.js", "text/javascript; charset=utf-8"),
                  "/monitor/review-cycles.js": ("review-cycles.js", "text/javascript; charset=utf-8"),
                  "/monitor/style.css": ("style.css", "text/css; charset=utf-8")}
        if target.path in assets:
            self._gate(api=False)
            name, media = assets[target.path]
            body = (HERE / "public" / name).read_bytes()
            self._headers(200, media, len(body)); self.wfile.write(body); return
        if not target.path.startswith("/api/os/"):
            return super()._get()
        self._gate()
        params = parse_qs(target.query, keep_blank_values=True)
        if any(len(v) != 1 for v in params.values()):
            raise InputError("Repeated local query parameters are not accepted")
        q = {k: v[0] for k, v in params.items()}
        path = target.path[len("/api/os/"):]
        d = self.domain
        if path == "cycle-context":
            return self._json({"workspace": str(d.ws.root), "name": d.ws.root.name})
        if path in {"cycles", "cycle", "cycle-request", "cycle-report", "cycle-report-html"}:
            self._cycle_branch()
        if path == "cycles":
            return self._json(review_cycles.view(d))
        if path == "cycle":
            return self._json(review_cycles.view(d, q["id"]))
        if path == "cycle-request":
            return self._json(review_cycles.request(d, q["id"]))
        if path == "cycle-report":
            return self._json(review_cycles.report(d, q["id"], int(q["version"])))
        if path == "cycle-report-html":
            raw = review_cycles.report_html(d, q["id"], int(q["version"])).encode("utf-8")
            self._headers(200, "text/html; charset=utf-8", len(raw)); self.wfile.write(raw); return
        if path == "gleif-intake":
            self._cycle_branch()
            return self._json(gleif_portfolio.operation(d, q["requestId"]))
        if path == "state":
            return self._json(d.state())
        if path == "contract":
            return self._json({"schema": "starforge.opensanctions-console.v1",
                "monitoring": MONITORING_DEFAULT, "publisherDelta": updates.DELTA_CONTRACT,
                "sourceFormats": ["Flat FtM JSON Lines", "Original dataset metadata", "Original delta JSON Lines", "Native statements CSV"],
                "auth": "Credentials stay in named environment references",
                "rawQuery": "/api/query"})
        if path == "entity":
            return self._json(d.entity(q["scope"], q["id"]))
        if path == "entities":
            return self._json(d.entity_page(q["scope"], int(q.get("offset", "0")), int(q.get("limit", "50"))))
        if path == "aliases":
            return self._json({"rows": d.aliases(q["scope"], q["id"])})
        if path == "changes":
            return self._json(d.changes(q["comparison"], int(q.get("offset", "0")), int(q.get("limit", "50")), q.get("kind"),
                                       material=q.get("material") == "true"))
        if path == "impacts":
            return self._json(d.impacted_cases(q["comparison"]))
        if path == "case":
            return self._json(d.case_history(q["id"]))
        if path == "statements":
            return self._json(d.statement_page(q["set"], q.get("entity"), int(q.get("offset", "0")), int(q.get("limit", "50"))))
        if path == "response":
            return self._json(matching.response_view(d, q["id"]))
        if path == "request":
            return self._json(d._one("requests", q["id"]))
        if path == "update-plan":
            return self._json(updates.update_plan(d, q["before"], q["after"], q["index"]))
        if path == "object":
            obj = d._one("objects", q["id"])
            return self._download(d.object_path(q["id"]), obj["name"], obj["media"])
        if path == "source":
            src = d.ws.source(q["id"])
            return self._download(d._source_path(q["id"]), src["name"], "application/x-ndjson")
        if path == "export":
            with d.mutex, d.ws.scratch() as temp:
                archive = temp / "OpenSanctions_Receiving_Workspace.zip"
                d.export_packet(archive)
                return self._download(archive, archive.name, "application/zip")
        return self._json({"error": "Unknown source-monitoring route"}, 404)

    def _post(self):
        target = urlsplit(self.path)
        if not target.path.startswith("/api/os/"):
            return super()._post()
        self._gate()
        d = self.domain
        path = target.path[len("/api/os/"):]
        if path == "object":
            if self.headers.get("X-Review-Workspace") is not None:
                self._cycle_branch()
            name = unquote(self.headers.get("X-Original-Name", "original"))
            source_url = unquote(self.headers.get("X-Original-URL", ""))
            body = self._body(MAX_SOURCE)
            if self.headers.get("X-Original-Compression") == "gzip":
                body = gzip.GzipFile(fileobj=body, mode="rb")
                if name.endswith(".gz"):
                    name = name[:-3]
            result = d.put_object(body, name, self.headers.get("Content-Type", "application/octet-stream"),
                                  {"url": source_url} if source_url else {})
            return self._json(result, 201)
        if path == "import":
            with d.mutex, d.ws.scratch() as temp:
                archive = temp / "incoming.zip"
                with archive.open("xb") as out:
                    archive.chmod(0o600)
                    stream = self._body(4 * MAX_SOURCE)
                    while chunk := stream.read(65536):
                        out.write(chunk)
                return self._json(d.import_packet(archive), 201)
        body = load_json(self._body(24 * 1024 * 1024).read())
        if not isinstance(body, dict):
            raise InputError("Expected the selected operation's JSON object")
        if path == "cycle-command":
            self._cycle_branch()
            try:
                return self._json(review_cycles.command(d, body), 201)
            except InputError as error:
                absent = False
                try:
                    absent = not review_cycles.request(d, body.get("requestId"))["committed"]
                except InputError:
                    pass  # Invalid history or request identity cannot establish an absent effect.
                return self._json({"error": str(error), "notCommitted": absent, "requestId": body.get("requestId")}, 400)
        if path == "published-edition":
            return self._json(updates.receive_published(d, body["metadataUrl"], body.get("entitlement")), 201)
        if path == "edition":
            with d.object_path(body["metadata"]).open("rb") as meta, d.object_path(body["entities"]).open("rb") as entities:
                return self._json(d.accept_edition(meta, entities, metadata_url=body["metadataUrl"],
                                    label=body.get("label"), entitlement=body.get("entitlement")), 201)
        if path == "gleif-preview":
            self._cycle_branch()
            return self._json(gleif_portfolio.preview(d, body["original"],
                offset=body.get("offset", 0), limit=body.get("limit", 50)))
        if path == "gleif-receive":
            self._cycle_branch()
            try:
                return self._json(gleif_portfolio.receive(d, body), 201)
            except InputError as error:
                not_committed = False
                try:
                    not_committed = not gleif_portfolio.operation(d, body.get("requestId"))["committed"]
                except InputError:
                    pass
                return self._json({"error": str(error), "requestId": body.get("requestId"),
                                   "notCommitted": not_committed}, 400)
        if path == "portfolio":
            with d.object_path(body["original"]).open("rb") as original:
                return self._json(d.accept_portfolio(original, key=body["key"], label=body["label"]), 201)
        if path == "statement-set":
            with d.object_path(body["original"]).open("rb") as original:
                return self._json(d.accept_statements(body["edition"], original, source_url=body["sourceUrl"],
                                  name=body.get("name", "statements.csv"), complete=body.get("complete", False),
                                  scope=body.get("scope")), 201)
        if path == "compare":
            return self._json(d.compare(body["before"], body["after"], body.get("statementBefore"), body.get("statementAfter")), 201)
        if path == "update":
            return self._json(updates.stage_update(d, body["before"], body["after"], body["index"], body["deltas"]), 201)
        if path == "fetch-update":
            return self._json(updates.fetch_update(d, body["before"], body["after"]), 201)
        if path == "select-update":
            return self._json(updates.select_update(d, body["id"], reviewer=body["reviewer"],
                                                    reason=body["reason"], expected=body.get("expected")))
        if path == "review":
            return self._json(d.review_change(body["change"], decision=body["decision"], reason=body["reason"],
                                              reviewer=body["reviewer"], authority_url=body.get("authorityUrl"),
                                              expected=body.get("expected")), 201)
        if path == "case":
            return self._json(d.save_case(**body), 201)
        if path == "profile":
            return self._json(matching.save_profile(d, body), 201)
        if path == "prepare":
            profile = body.pop("profile")
            return self._json(matching.prepare(d, profile, **body), 201)
        if path == "dispatch":
            return self._json(matching.dispatch(d, body["id"], expected=body["expected"]))
        if path == "receive-response":
            data = d.object_path(body["original"]).read_bytes()
            return self._json(matching.receive(d, body["id"], data, status=body["status"],
                                               headers=body.get("headers"), source_note=body["sourceNote"],
                                               expected=body.get("expected")), 201)
        return self._json({"error": "Unknown source-monitoring operation"}, 404)

class OperatorServer(ndjson_application.RetainedServer):
    def __init__(self, workspace, port=0):
        self.domain = getattr(workspace, "opensanctions", None) or Domain(workspace)
        matching.recover_interrupted(self.domain)
        super().__init__(workspace, port, assets_directory=ndjson_application.HERE / "public", handler_class=Handler)
        self.launch = None
        self.url = self.origin + "/monitor#" + self.token

/* MIT. Explicit research intake using original objects, portfolio and custody history. */
export async function mountGleifIntake({root,api,refresh,getState,escape,download,openPortfolio,useMonitoringPolicy,message}) {
  const e=escape,context=await api("cycle-context"),branch=context.workspace;
  root.innerHTML='<h2>Receive GLEIF company research</h2><p>Open a complete handover from the Company research application. Review its exact source edition and LegalEntity fields before receiving the portfolio.</p>'+
    '<form data-intake-form><label>Complete GLEIF Monitoring handover<input name="file" type="file" accept=".json,application/json" required></label>'+
    '<div class="form-grid"><label>Receiving reviewer<input name="reviewer" required maxlength="160"></label><label>Intake note<textarea name="note" rows="2" maxlength="4000"></textarea></label></div>'+
    '<button type="submit">Inspect source and field mapping</button></form>'+
    '<div data-intake-preview aria-live="polite"></div><div class="actions"><button type="button" data-intake-receive disabled>Receive reviewed counterparties</button>'+
    '<button type="button" data-intake-prev hidden>Previous companies</button><button type="button" data-intake-next hidden>Next companies</button></div>'+
    '<div data-intake-pending></div><h3>Original research handovers</h3><div data-intake-history></div>';
  const form=root.querySelector('[data-intake-form]'),panel=root.querySelector('[data-intake-preview]'),receiveButton=root.querySelector('[data-intake-receive]');
  const field=name=>form.elements.namedItem(name),slot='gleif-monitoring-intake/'+branch;
  let selected=null,preview=null,pending=null,generation=0,busy=false,policy=null;
  const call=(path,body,options={})=>api(path,body,{...options,headers:{"X-Review-Workspace":encodeURIComponent(branch),...options.headers}});
  let saved;try{saved=JSON.parse(localStorage.getItem(slot)??'null');}catch{}
  if(saved){field('reviewer').value=saved.reviewer??'';field('note').value=saved.note??'';pending=saved.pending??null;}
  const save=()=>localStorage.setItem(slot,JSON.stringify({reviewer:field('reviewer').value,note:field('note').value,pending}));
  const current=turn=>turn===generation&&root.isConnected;
  function pendingView(){
    const node=root.querySelector('[data-intake-pending]');
    node.innerHTML=pending?'<p><strong>Original intake request retained.</strong> Continue its exact file and reviewer choices after an uncertain response.</p><button type="button" data-intake-resume>Continue original intake</button><details><summary>Request identity</summary><pre>'+e(JSON.stringify(pending,null,2))+'</pre></details>':'';
    node.querySelector('[data-intake-resume]')?.addEventListener('click',()=>perform(pending));
    receiveButton.disabled=busy||!!pending||!preview;
  }
  function render(){
    if(!preview)return;
    policy=preview.monitoringDefaults;
    panel.innerHTML='<h3>'+e(preview.title)+'</h3><p>'+preview.count+' companies · portfolio '+e(preview.portfolioKey)+' · original capture '+e(preview.captureIds[0])+'</p>'+
      '<p>'+e(preview.interpretation)+'</p><div class="table-wrap"><table><thead><tr><th>Company / LEI</th><th>Exact copied fields</th></tr></thead><tbody>'+
      preview.rows.map(row=>'<tr><td>'+e(row.caption)+'<br><code>'+e(row.properties.leiCode[0])+'</code></td><td><pre>'+e(JSON.stringify(row.properties,null,2))+'</pre></td></tr>').join('')+
      '</tbody></table></div><p>Companies '+(preview.offset+1)+'–'+(preview.offset+preview.rows.length)+' of '+preview.count+'. All selected records and the complete original project travel with this intake.</p>';
    root.querySelector('[data-intake-prev]').hidden=preview.offset===0;
    root.querySelector('[data-intake-next]').hidden=preview.nextOffset===null;pendingView();
  }
  async function inspect(offset=0) {
    const turn=++generation,original=selected;
    receiveButton.disabled=true;panel.textContent='Verifying the complete original project, response pages and mapping…';
    try{const value=await call("gleif-preview",{original,offset,limit:50});if(!current(turn)||selected!==original)return;
      if(value.workspace!==branch)throw Error('The preview belongs to another workspace.');
      preview=value;render();
    }catch(error){if(current(turn)){preview=null;panel.textContent=error.message;message(error.message,true);}}
  }
  form.addEventListener('input',()=>save());
  field('file').addEventListener('change',()=>{generation++;selected=null;preview=null;receiveButton.disabled=true;panel.textContent='Inspect the selected original file.';});
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(busy)return;const file=field('file').files[0];if(!file)return;
    const turn=++generation;busy=true;receiveButton.disabled=true;
    try{const object=await call("object",file,{headers:{"Content-Type":"application/json","X-Original-Name":encodeURIComponent(file.name)}});
      if(!current(turn)||field('file').files[0]!==file)return;selected=object.id;await inspect();
    }catch(error){if(current(turn))message(error.message,true);}
    finally{busy=false;pendingView();}
  });
  async function perform(original) {
    if(busy||!original)return;busy=true;pendingView();
    try{
      const result=await call("gleif-receive",original);
      if(result.receipt?.requestId!==original.requestId||result.receipt.original!==original.original)throw Error('The retained intake response belongs to a different request.');
      localStorage.setItem(slot+'/history/'+original.requestId,JSON.stringify({request:original,result}));
      if(pending?.requestId===original.requestId){pending=null;save();}
      await refresh();await openPortfolio(result.portfolio.id);
      message('The original research portfolio and complete project are retained. Native matching remains an explicit separate operation.');
    }catch(error){
      if(error.native?.notCommitted===true&&error.native?.requestId===original.requestId){
        localStorage.setItem(slot+'/history/'+original.requestId,JSON.stringify({request:original,rejected:error.native}));
        if(pending?.requestId===original.requestId){pending=null;save();}
      }
      message(error.message,true);
    }finally{busy=false;pendingView();}
  }
  receiveButton.addEventListener('click',()=>{
    if(!preview||busy||pending)return;
    if(!field('reviewer').value.trim()){message('Enter the receiving reviewer before accepting the portfolio.',true);return;}
    pending={requestId:crypto.randomUUID(),original:preview.original,expectedPreviewSha256:preview.previewSha256,
      reviewer:field('reviewer').value,note:field('note').value};save();pendingView();perform(pending);
  });
  root.querySelector('[data-intake-prev]').addEventListener('click',()=>{if(preview&&!busy)inspect(Math.max(0,preview.offset-50));});
  root.querySelector('[data-intake-next]').addEventListener('click',()=>{if(preview?.nextOffset!==null&&preview&&!busy)inspect(preview.nextOffset);});
  const history=root.querySelector('[data-intake-history]');
  history.addEventListener('click',async event=>{
    const button=event.target.closest('button');if(!button)return;
    try{
      if(button.dataset.object)await download("object?"+new URLSearchParams({id:button.dataset.object}),button.dataset.name);
      if(button.dataset.portfolio)await openPortfolio(button.dataset.portfolio);
      if(button.dataset.policy){const source=await call("gleif-preview",{original:button.dataset.policy,limit:1});useMonitoringPolicy(source.monitoringDefaults);}
    }catch(error){message(error.message,true);}
  });
  pendingView();
  return {refresh(state){
    const receipts=state?.research_intakes??[];
    history.innerHTML=receipts.length?receipts.map(receipt=>'<article><h4>'+e(state.portfolios.find(row=>row.id===receipt.portfolioId)?.label??receipt.portfolioId)+'</h4>'+
      '<p>'+e(receipt.reviewer)+' · original capture '+e(receipt.captureIds.join(', '))+'</p><p>'+e(receipt.note)+'</p><div class="actions">'+
      '<button type="button" data-portfolio="'+e(receipt.portfolioId)+'">Open original portfolio</button>'+
      '<button type="button" data-policy="'+e(receipt.original)+'">Use LEI in this case monitoring draft</button>'+
      '<button type="button" data-object="'+e(receipt.original)+'" data-name="gleif-monitoring-portfolio.json">Complete handover</button>'+
      Object.entries(receipt.files).map(([name,id])=>'<button type="button" data-object="'+e(id)+'" data-name="'+e(name)+'">'+e(name)+'</button>').join('')+
      '</div><details><summary>Complete receiving identity</summary><pre>'+e(JSON.stringify(receipt,null,2))+'</pre></details></article>').join(''):'<p>No GLEIF research handover has been received.</p>';
    pendingView();
  }};
}

